--
-- Name: v_cmo_items; Type: VIEW; Schema: public; Owner: yuri_user
--

CREATE VIEW public.v_cmo_items AS
 SELECT items.item_code,
    items.item_name,
    items.weight,
    (((COALESCE(items.length_cm, (0)::numeric) * COALESCE(items.width_cm, (0)::numeric)) * COALESCE(items.height_cm, (0)::numeric)) / 1000000.0) AS volume
   FROM public.items;


ALTER TABLE public.v_cmo_items OWNER TO yuri_user;

--
-- Name: v_cmo_items_v2; Type: VIEW; Schema: public; Owner: yuri_user
--

